import type { ConnectProviderRequest, ProviderConnection, ProviderId } from '@/types/provider';
import { getByokAdapter } from './adapter';

export const listProviderConnections = (): Promise<ProviderConnection[]> => getByokAdapter().listProviders();
export const connectProvider = (request: ConnectProviderRequest): Promise<ProviderConnection> => getByokAdapter().connectProvider(request);
export const disconnectProvider = (provider: ProviderId): Promise<void> => getByokAdapter().disconnectProvider(provider);
export const testProviderConnection = (provider: ProviderId) => getByokAdapter().testProvider(provider);
